const insertErrorLog = flow.get("insertErrorLog");
const pool = flow.get('pg_pool');

if (!pool) {
    msg.error = {
        message: "PostgreSQL pool not initialized"
    };

    node.error(msg.error?.message, msg);
    return msg;
};

try {
    const queryText = msg.payload;
    const values = parseQueryParameters(msg.queryParameters);

    if (!queryText || typeof queryText !== 'string' || queryText.trim() === '') {
        msg.error = {
            message: "Invalid query"
        };
        await insertErrorLog({
            code: 'ERR_INVALID_QUERY',
            message: msg.error?.message,
            context: {
                query: queryText
            }
        });

        node.error(msg.error, msg);
        return msg;
    };

    const res = await pool.query(queryText, values);

    msg.payload = res.rows;
    node.send(msg);
} catch (err) {
    msg.error = err;
    node.error(msg.error, msg);

    node.send(msg);
};

// ----- functions -----

function parseQueryParameters(params) {
    if (!params) return [];
    if (Array.isArray(params)) return params;
    if (typeof params === 'object') return Object.values(params);

    throw new Error("Invalid queryParameters");
};

