const validateName = (name) => {
    const trimmed = name.trim();

    if (trimmed.length < 2) {
        return { isValid: false, error: "Ім'я контакту має містити мінімум 2 символи" };
    };

    if (trimmed.length > 50) {
        return { isValid: false, error: "Ім'я контакту занадто довге (максимум 50 символів)" };
    };

    const nameRegex = /^[A-Za-zА-Яа-яЁёІіЇїЄєҐґ0-9\s'-]+$/u;
    if (!nameRegex.test(trimmed)) {
        return { 
            isValid: false, 
            error: "Ім'я може містити лише букви (латиниця або кирилиця), цифри, пробіли, апостроф або дефіс" 
        };
    };

    return { isValid: true, error: null, value: trimmed };
};

const validateDate = (dateString) => {
    const dateRegex = /^\d{4}-\d{2}-\d{2}$/;

    if (!dateRegex.test(dateString)) {
        return {
            isValid: false,
            error: "Неправильний формат дати. Використовуйте РІК-МІСЯЦЬ-ДЕНЬ (наприклад: 2024-12-25)"
        };
    };

    const [year, month, day] = dateString.split('-').map(Number);
    const inputDate = new Date(year, month - 1, day);

    if (
        inputDate.getFullYear() !== year ||
        inputDate.getMonth() !== month - 1 ||
        inputDate.getDate() !== day
    ) {
        return { isValid: false, error: "Некоректна дата (така дата не існує)" };
    };

    const today = new Date();
    today.setHours(0, 0, 0, 0);

    if (inputDate > today) {
        return { isValid: false, error: "Дата не може бути в майбутньому" };
    };

    return {
        isValid: true,
        error: null,
        value: dateString,
        dateObject: inputDate
    };
};

