const formatOrder = (order, i) => {
    const {
        order_id,
        dolibarr_ref,
        customer_name,
        customer_phone,
        total_price,
        notes,
        items = []
    } = order;

    const itemsList = items.map(item => {
        const productName = item.product_name
            ?.replace(/^Cremosa(?:\s+de)?\s*/i, '')
            .trim();

        const variantName = item.variant_name
            ?.split('(')[0]
            .trim()
            .toLowerCase();

        const dietary = [];
        if (item.is_gluten_free) dietary.push('sin gluten');
        if (item.is_lactose_free) dietary.push('sin lactosa');
        const dietaryText = dietary.length ? ` (${dietary.join(', ')})` : '';

        return `    • ${item.quantity}× ${productName} ${variantName}${dietaryText}`;
    }).join('\n');

    return (
        `\n${i + 1}. 🧾 ${order_id}` +
        `${dolibarr_ref ? `\n[${dolibarr_ref}]` : ''} ` +
        `\n<i>${total_price}€</i>\n` +
        `👤 <b>${customer_name}</b>\n` +
        `📞 ${customer_phone}\n` +
        `${itemsList}` +
        `${notes ? `\n📝 <i>${notes}</i>` : ''}`
    );
};


const splitIntoChunks = (text, limit) => {
    if (text.length <= limit) return [text];

    const chunks = [];
    let currentChunk = "";
    const lines = text.split('\n');

    for (const line of lines) {
        if ((currentChunk + line).length > limit) {
            chunks.push(currentChunk.trim());
            currentChunk = line + "\n";
        } else {
            currentChunk += line + "\n";
        }
    }
    if (currentChunk) chunks.push(currentChunk.trim());
    return chunks;
};

const finalMessages = [];
const header = `<i>${formattedDate} · ${orders.length} pedidos</i>\n`;

const processShift = (shiftOrders, title) => {
    if (!shiftOrders?.length) return;

    let shiftText = `<b><i>${title} (${shiftOrders.length})</i></b>\n`;
    shiftText += shiftOrders.map((o, i) => formatOrder(o, i)).join('\n');

    const chunks = splitIntoChunks(shiftText, MAX_LENGTH - header.length);

    chunks.forEach((chunk, index) => {
        const prefix =
            index === 0
                ? header
                : `<i>↪ Continuación ${title}</i>\n`;

        finalMessages.push({
            message: prefix + chunk,
            topic: 'vender'
        });
    });
};

